window.products.push({"id":761485,"name":"Soleus Air Heater for Home and Office, 2 Heat Settings, Overheating and Tip-Over Protection, Easy to Use Manual Controls, 60 Minute Timer (Ceramic 1,5","category":"homeandappliances","retail price":62.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/61h3LDv3P3L._AC_SL1500_.jpg","description":"EXTREME COMFORT: Two heat settings 1000W and 1500W for comfortable warmth and custom comfort for your needs FAST AND EFFICIENT: 90-degree left-to-right oscilliation allows you to put heat where it is needed most while maintaining a consistent temperature throughout the space TIP OVER PROTECTION: Includes an overheat protection sensor and an automatic fail-safe that cuts power to the unit if it's accidentally tipped over. SAFE TO USE: Overheat sensor automatically monitors the internal temperature and will turn off the unit if an overheat is detected EASY TO USE: Mechanical controls keeps operation simple and reliable while keeping the convenience and reliability of top heating technology","images":["https://m.media-amazon.com/images/I/61h3LDv3P3L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Soleus Air","source_asin":"B09MG6KFFQ","category_path":"Home & Kitchen"},"sku":"BM-761485","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B09MG6KFFQ","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B09MG6KFFQ","price_pending":true,"merchant_ready":false});
