window.products.push({"id":761487,"name":"WMF Vitalis Cooking System II, Large, Silver","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/91SovVNBm-L._AC_SL1500_.jpg","description":"WMF's Vitalis Cooking System II is made of 18/10 stainless steel and comes with it's own steaming rack& thermometer. The lid is glass and has a 100-percent silicone seal to keep nutrients and flavors from escaping. The base is WMF's Trans Thermo base which is an aluminum core surrounded by stainless steel. The ensures excellent heat retention, so the unit may be used on a single burner & the heat will diffuse and be retained in the core.","images":["https://m.media-amazon.com/images/I/91SovVNBm-L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"WMF","source_asin":"B00RGWGP6S","category_path":"Home & Kitchen"},"sku":"BM-761487","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00RGWGP6S","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00RGWGP6S","price_pending":true,"merchant_ready":false});
